// Authored content for 3.1.6 Living organisms vary. OxfordAQA 9610 v5.1 (page 16) gives this topic as ONE reference
// with six requirements and NO numbered subsections. The sections A–E below are internal teaching divisions only.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.variationArt, S = window.BIO.statsModel;
  const R = "3.1.6";
  const P = (slot) => window.BIO.views.photo(slot);
  const pct = (k) => (100 * S.within(k)).toFixed(k === 1 ? 0 : 1);
  // Illustrative datasets for Interpret the Data (constructed; realistic magnitudes; not published measurements)
  const datasets = [
    { title: "Dataset 1 (illustrative): shell length of dog whelks on two shores", html: `<table class="tbl"><thead><tr><th></th><th>Sheltered shore</th><th>Exposed shore</th></tr></thead><tbody><tr><th>Sample size n</th><td>30</td><td>30</td></tr><tr><th>Mean shell length / mm</th><td>28.4</td><td>24.1</td></tr><tr><th>Standard deviation / mm</th><td>2.1</td><td>2.3</td></tr></tbody></table>` },
    { title: "Dataset 2 (illustrative): leaf length of a single oak tree, sun and shade leaves", html: `<table class="tbl"><thead><tr><th></th><th>Sun leaves</th><th>Shade leaves</th></tr></thead><tbody><tr><th>Sample size n</th><td>8</td><td>8</td></tr><tr><th>Mean leaf length / mm</th><td>71</td><td>84</td></tr><tr><th>Standard deviation / mm</th><td>14</td><td>15</td></tr></tbody></table>` },
    { title: "Dataset 3 (illustrative): mass of seeds from two plant species", html: `<table class="tbl"><thead><tr><th></th><th>Species X</th><th>Species Y</th></tr></thead><tbody><tr><th>Sample size n</th><td>100</td><td>100</td></tr><tr><th>Mean seed mass / mg</th><td>12.6</td><td>31.9</td></tr><tr><th>Standard deviation / mg</th><td>1.8</td><td>4.0</td></tr></tbody></table>` },
  ];
  window.BIO.content[R] = {
    status: "reviewed",
    banner: "snail-banding", bannerText: "No two living things are the same. Variation, and how to measure it fairly, is where every investigation in biology begins.",
    keywords: ["variation", "intraspecific", "interspecific", "genetic", "environmental", "genotype", "phenotype", "random sampling", "sample size", "bias", "representative", "chance", "normal distribution", "mean", "standard deviation", "continuous", "discontinuous", "correlation", "causation", "twins", "clone"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.1.6, a single reference; OxfordAQA gives this topic no numbered subsections).</strong> (1) Intraspecific variation is variation between members of a species; interspecific variation is variation between species. (2) In investigations of intraspecific variation, the need for random sampling and the importance of chance in contributing to the difference between samples. (3) The importance of appropriate sample size in ensuring that data are representative. (4) The concept of normal distribution about a mean. (5) Understanding of mean and standard deviation as measures of variation within a sample; <em>students will not be required to calculate standard deviation in questions on written papers</em>. (6) Similarities and differences between individuals within a species may be the result of genetic factors, differences in environmental factors or a combination of both. You should be able to analyse and interpret data referring to intraspecific and interspecific variation. The headings A–E below are this site's teaching sections, not specification numbers. <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">extension</span></div>
<h2 data-stmt="${R}.s1">A. Intraspecific and interspecific variation <span class="badge teal">required</span></h2>
<ul><li><strong>Intraspecific variation</strong> is variation between members of the same species: the heights of the oak trees in a wood, the shell patterns of the banded snails in a hedge, the masses of the seeds from one plant, the eye colours in a class.</li>
<li><strong>Interspecific variation</strong> is variation between species: an oak and a beech differ in leaf shape, bark and the fungi they host; a limpet and a dog whelk differ in shell form and diet.</li></ul>
<p>Both kinds are the raw material of biology: interspecific variation is what classification and evolution describe (3.1.10, 3.3.8), while intraspecific variation is what natural selection acts on, and what every experiment has to allow for before it can claim an effect.</p>
<div class="grid grid-2">${P("snail-banding")}${P("ladybird-morphs")}</div>
<p><span class="badge">supporting</span> Within a species, some characteristics vary <strong>continuously</strong> (height, mass, leaf length: any value within a range, usually controlled by many genes and the environment, and often giving an approximately normal distribution when plotted) and others <strong>discontinuously</strong> (blood group, banded or unbanded shells: a few distinct categories, usually controlled by one or a few genes). The statistics in sections C and D apply to continuous variation. OxfordAQA does not list these terms as required; they are useful for interpreting data.</p>
<h2 data-stmt="${R}.s5">B. Genetic and environmental influences <span class="badge teal">required</span></h2>
<p>Similarities and differences between individuals within a species may result from <strong>genetic factors</strong> (different alleles of their genes), from <strong>differences in environmental factors</strong> (light, nutrients, temperature, diet, disease, competition) or, most often, from a <strong>combination of both</strong>.</p>
<ul><li><strong>Genetic only:</strong> human blood groups are fixed by the alleles inherited; no environment changes them.</li><li><strong>Environmental only:</strong> cuttings from one plant (clones, genetically identical) grown in sun and in shade differ in height and leaf size; the scars on an animal; the colour of hydrangea flowers, which depends on soil acidity in plants of the same genotype.</li><li><strong>Both:</strong> human height, the yield of a wheat variety, the mass of a fish. The genotype sets a range; the environment decides where in it the individual falls.</li></ul>
<p><span class="badge">supporting</span> The <strong>genotype</strong> is the genetic constitution of an organism (its alleles); the <strong>phenotype</strong> is its observable characteristics, the result of the genotype, the environment and their interaction (defined formally in 3.3.6). How to separate the two experimentally: keep one constant and vary the other. Clones or identical twins hold the genotype constant, so any difference between them is environmental; individuals of different genotype raised in one controlled environment show genetic differences. Where the environment affects different genotypes by different amounts (the interactive shows a high-altitude plant that responds much less to altitude beside a lowland plant that responds strongly), the phenotype cannot be partitioned into a fixed genetic share and a fixed environmental share: the contributions are not simply additive. Be cautious with claims of the form "height is 80 % genetic".</p>
${P("hydrangea-colour")}
<h2 data-stmt="${R}.s2">C. Random sampling and sample size <span class="badge teal">required</span></h2>
<p>To describe intraspecific variation you measure a <strong>sample</strong> because the whole population is too large to measure. The sample is only useful if it is <strong>representative</strong>: its distribution of values resembles the population's.</p>
<ul><li><strong>Random sampling</strong> gives every individual an equal chance of being selected, so the sampler's choices cannot bias the result. In practice: lay a grid over the area, generate random coordinates (random-number tables or a calculator), and measure whatever lies at each coordinate (for example in a quadrat). <span class="badge">supporting</span> Systematic sampling along a transect is used when there is a gradient to describe; it is not random, but it is unbiased if the interval does not match any pattern in the population.</li>
<li><strong>Sampling bias</strong> arises when the chance of selection depends on the individual: choosing specimens that look typical, large or undamaged; sampling where access is easiest (the path, the near end of the shore); measuring only those that stay still. Bias is not reduced by taking more samples the same way.</li>
<li><strong>Chance</strong> still affects a random sample. Two random samples from the same population will differ from each other, and from the population, simply because different individuals happened to be chosen. The <strong>difference between samples</strong> therefore has two sources: real differences (if the samples come from different populations or treatments) and chance. Statistics exist to judge which is more likely.</li>
<li><strong>Sample size</strong>. Larger random samples <em>tend</em> to give means closer to the population mean and a better picture of its spread: the scatter of sample means shrinks in proportion to 1/√n, so four times the sample size roughly halves it (<span class="badge">supporting</span>). A larger sample is not guaranteed to be closer than a smaller one on any single occasion, and a large biased sample is still biased. "Appropriate sample size" means large enough that chance differences are small compared with the differences you want to detect, and practicable to collect.</li></ul>
${P("quadrat-sampling")}
<h2 data-stmt="${R}.s3 ${R}.s4 ${R}.s6">D. Normal distribution, mean and standard deviation <span class="badge teal">required</span></h2>
<p>When a continuously varying characteristic is measured in a large random sample and plotted as a frequency histogram, the values usually cluster around a central value and tail off symmetrically on either side: a bell-shaped <strong>normal distribution about the mean</strong>.</p>
${A.normalCurve({ mu: 30, sd: 4, shade: 1, width: 620, xLabel: "shell length / mm (illustrative population: mean 30, SD 4)" })}
<ul><li>The <strong>mean</strong> (the sum of the values divided by their number) is the measure of central tendency: it locates the centre of the distribution. In a normal distribution the mean, median and mode coincide and the curve is <strong>symmetrical</strong> about them.</li>
<li>The <strong>standard deviation (SD)</strong> measures the spread of the values around the mean: a small SD means the values are tightly clustered (little variation); a large SD means they are widely spread (much variation). In a normal distribution about <strong>${pct(1)} %</strong> of values lie within one SD of the mean (from one SD below to one SD above), about <strong>${pct(2)} %</strong> within two SDs and about <strong>${pct(3)} %</strong> within three.</li>
<li>Reading a result such as "mean 30.0 mm, SD 4.0 mm, n = 50": the typical limpet is about 30 mm; roughly two thirds of them are between 26 and 34 mm; about 95 % are between 22 and 38 mm, and almost all (99.7 %) between 18 and 42 mm.</li>
<li>Comparing datasets: two groups can have the same mean but different SDs (one more variable), or different means with SDs so large that their ranges <strong>overlap</strong> heavily. When the mean ± SD ranges overlap, many individuals of one group fall within the normal range of the other, so a difference between the means may be due to chance; the larger the samples and the smaller the overlap, the more confident you can be. Standard deviation on its own does <em>not</em> tell you whether a difference is statistically significant: that needs a statistical test (3.3.6 and the Maths Hub cover the tests OxfordAQA names; the most direct way to judge whether two means differ is to compare their 95 % confidence limits, based on the standard error, which OxfordAQA also lists among its maths skills).</li></ul>
<p class="small"><span class="badge">supporting</span> <strong>Overlap is not a test.</strong> Whether or not the mean ± 1 SD ranges of two samples overlap does not by itself show whether the two means differ significantly: that is decided with a statistical test or from the standard error of each mean, and no such calculation is required at AS.</p>
<div class="notice amber"><strong>Examination note.</strong> You must understand and interpret standard deviation; the specification states that you will not be required to calculate it in written papers. The optional calculator below exists only to show where the number comes from; it is marked "supporting" and no question on this site asks you to compute an SD by hand.</div>
<h2 data-stmt="${R}.s6">E. Correlation and causation <span class="badge">supporting: scientific reasoning</span></h2>
<p>This is not a separately numbered requirement of 3.1.6; it is reasoning you need whenever you "analyse and interpret data" about variation (and it is stated among the Unit 2 biological principles). A <strong>correlation</strong> exists when one variable changes as another changes (shell length rises with distance down the shore). A correlation does not by itself establish <strong>causation</strong>: the relationship may be reversed, both variables may be driven by a third, <strong>confounding</strong> variable (wave exposure, food supply and predators all change down the shore, so any of them, rather than distance itself, could cause the pattern), or the pattern may be chance in a small sample. To claim a cause you need a controlled experiment in which only the suspected cause is changed, or a well-supported mechanism, or both.</p>`,
    diagrams: [
      { id: "d-3.1.6-1", title: "A normal distribution with its standard deviation bands", status: "reviewed", caption: "Symmetrical about the mean; about 68 % of values lie within one SD either side of the mean (the two adjacent intervals), about 95 % within two and about 99.7 % within three. Model curve (mean 30, SD 4).", alt: "Bell-shaped curve with the mean marked and vertical lines at plus and minus one, two and three standard deviations; the central band is shaded.", svg: A.normalCurve({ mu: 30, sd: 4, shade: 1, xLabel: "measurement (e.g. shell length / mm)" }) },
      { id: "d-3.1.6-2", title: "Same mean, different spread", status: "reviewed", caption: "Two normal distributions with the same mean (30) but SDs of 2 (dashed) and 5: the smaller SD gives a taller, narrower curve, meaning less variation. Model curves.", alt: "Two bell curves centred on the same value, one tall and narrow and one low and wide.", svg: A.normalCurve({ mu: 30, sd: 5, mu2: 30, sd2: 2, shade: 0, xLabel: "measurement" }) },
      { id: "d-3.1.6-3", title: "Different means, overlapping ranges", status: "reviewed", caption: "Dataset A (mean 28, SD 4) and dataset B (mean 33, SD 4, dashed). The means differ by 5 but the ±1 SD ranges overlap from 29 to 32: many individuals could belong to either group, so the difference needs careful interpretation. Model curves.", alt: "Two overlapping bell curves of the same width with centres five units apart.", svg: A.normalCurve({ mu: 28, sd: 4, mu2: 33, sd2: 4, shade: 0, xLabel: "measurement" }) },
    ],
    interactives: [
      { kind: "variationIdentify", title: "Variation Identification Challenge", note: "Real biological examples: decide whether each describes intraspecific or interspecific variation, and whether genetic or environmental causes are implied.",
        questions: [
          { id: "q-3.1.6-vi1", ref: R, stmts: ["3.1.6.s1"], type: "mcq", marks: 1, stem: "The grove snail Cepaea nemoralis occurs with yellow, pink or brown shells, with or without dark bands, within one hedgerow.", options: ["Intraspecific variation", "Interspecific variation"], answer: 0, explanation: "One species (C. nemoralis) showing different phenotypes: intraspecific, and in this case largely genetic (shell colour and banding are inherited)." },
          { id: "q-3.1.6-vi2", ref: R, stmts: ["3.1.6.s1"], type: "mcq", marks: 1, stem: "The two-spot ladybird (Adalia bipunctata) and the seven-spot ladybird (Coccinella septempunctata) differ in size, spot number and the aphid species they prefer.", options: ["Intraspecific variation", "Interspecific variation"], answer: 1, explanation: "Two different species: interspecific." },
          { id: "q-3.1.6-vi3", ref: R, stmts: ["3.1.6.s1", "3.1.6.s5"], type: "mcq", marks: 1, stem: "Cuttings taken from one hydrangea plant produce blue flowers in acidic soil and pink flowers in alkaline soil.", options: ["Intraspecific variation with a genetic cause", "Intraspecific variation with an environmental cause", "Interspecific variation"], answer: 1, explanation: "Clones have the same genotype; the difference is caused by the soil (aluminium availability at low pH)." },
          { id: "q-3.1.6-vi4", ref: R, stmts: ["3.1.6.s1", "3.1.6.s5"], type: "mcq", marks: 1, stem: "Human ABO blood groups: in one population 44 % are group O, 42 % group A, 10 % group B and 4 % group AB.", options: ["Intraspecific variation, caused by genetic factors", "Intraspecific variation, caused by environmental factors", "Interspecific variation"], answer: 0, explanation: "One species; a person's blood group is fixed by the alleles they inherit and is not changed by the environment, so there are a few distinct groups." },
          { id: "q-3.1.6-vi5", ref: R, stmts: ["3.1.6.s1", "3.1.6.s5"], type: "mcq", marks: 1, stem: "Oak trees (Quercus robur) in a wood range in height from 8 m to 31 m.", options: ["Intraspecific variation, caused by both genetic and environmental factors", "Interspecific variation", "Intraspecific variation, caused by genetic factors only"], answer: 0, explanation: "One species; height can take any value in a range and depends on alleles as well as age, light, soil and competition, so it is the result of a combination of genetic and environmental factors." },
          { id: "q-3.1.6-vi6", ref: R, stmts: ["3.1.6.s5", "3.1.6.s6"], type: "mcq", marks: 1, stem: "Same-sex twins raised together: identical twins differ in body mass by 2 kg on average; non-identical twins differ by 6 kg on average.", options: ["The identical twins' difference is environmental; the larger difference in non-identical twins shows a genetic component", "The difference in identical twins is genetic", "This is interspecific variation"], answer: 0, explanation: "Both groups share an environment. Identical twins share a genotype, so their difference is environmental; non-identical twins also differ genetically, which accounts for the extra difference." },
          { id: "q-3.1.6-vi7", ref: R, stmts: ["3.1.6.s1", "3.1.6.s5"], type: "short", marks: 3, stem: "A student measured the length of 20 leaves from a holly bush and 20 from a laurel bush, and 20 leaves from the shaded side and 20 from the sunny side of the same holly bush. Which comparison shows intraspecific variation, which shows interspecific variation, and which comparison could be explained by environmental factors alone? Justify each. (3 marks)", scheme: [{ point: "Holly v laurel: interspecific (two species)", marks: 1 }, { point: "Shaded v sunny side of one bush: intraspecific (same species; in fact the same individual)", marks: 1 }, { point: "The sun/shade comparison is explicable by environment alone because the leaves share one genotype (one plant); the holly/laurel difference is genetic (different species) though environment also contributes", marks: 1 }], model: "The holly and laurel comparison is interspecific variation because the leaves come from two different species. The shaded and sunny leaves of one holly bush show intraspecific variation; they are from the same species and even the same individual. Because leaves on one plant share the same genotype, any difference between the shaded and sunny leaves must be environmental (light), whereas the holly–laurel difference reflects genetic differences between species, with environment contributing too.", commonErrors: "Calling the sun/shade difference genetic." },
        ] },
      { kind: "geneEnvInvestigation", title: "Genes, Environment or Both?", note: "Illustrative transplant and twin data: hold the genotype constant to see environmental effects, hold the environment constant to see genetic ones, and notice when the two interact." },
      { kind: "samplingSim", title: "Sampling Investigation Simulator", note: "A shore of 400 limpets with a known distribution of shell length. Choose a method and a sample size, take samples, compare the sample means with the population mean and watch chance and bias at work." },
      { kind: "normalExplorer", title: "Normal Distribution Explorer", note: "Change the mean and standard deviation, shade ±1, ±2 or ±3 SD, overlay a second dataset and read what the overlap means." },
      { kind: "dataInterpret", title: "Interpret the Data", note: "Three illustrative datasets with means, standard deviations and sample sizes: compare, interpret and decide which conclusions are justified.", datasets,
        questions: [
          { id: "q-3.1.6-di1", ref: R, stmts: ["3.1.6.s4", "3.1.6.s6"], type: "short", marks: 3, stem: "Dataset 1. Compare the dog whelks on the two shores and explain how far the data justify the conclusion that whelks on exposed shores are smaller. (3 marks)", scheme: [{ point: "Exposed-shore mean is 4.3 mm lower (24.1 v 28.4); SDs similar (2.1, 2.3), so spread is similar", marks: 1 }, { point: "Mean ± SD ranges (26.3–30.5 v 21.8–26.4) barely overlap and n = 30 is reasonable, so a real difference is likely", marks: 1 }, { point: "But a statistical test would be needed to be confident, and the data do not show the cause (wave exposure, food, predators are confounded)", marks: 1 }], model: "The exposed-shore whelks have a mean shell length 4.3 mm lower than the sheltered-shore whelks, and the standard deviations are similar, so the two samples are equally variable. The ranges of mean ± one SD (26.3–30.5 mm and 21.8–26.4 mm) barely overlap, and with 30 individuals in each sample this is unlikely to be chance, so the conclusion that whelks on the exposed shore are smaller is reasonably supported. A statistical test would be needed to put a probability on it, and the data say nothing about why: exposure, food supply and predation differ between the shores at the same time.", commonErrors: "Treating a difference in means as proof without considering spread or sample size." },
          { id: "q-3.1.6-di2", ref: R, stmts: ["3.1.6.s4", "3.1.6.s6", "3.1.6.s2"], type: "short", marks: 3, stem: "Dataset 2. A student concludes: 'Shade leaves are longer than sun leaves.' Evaluate this conclusion. (3 marks)", scheme: [{ point: "Shade mean is 13 mm higher, but SDs (14, 15) are as large as the difference", marks: 1 }, { point: "Mean ± SD ranges (57–85 v 69–99) overlap widely and n = 8 is small, so the difference could be chance", marks: 1 }, { point: "Conclusion is an overstatement: tentative at best; larger samples and a statistical test needed. (Credit noting the comparison is within one genotype, so any real difference would be environmental)", marks: 1 }], model: "Although the shade leaves have a mean 13 mm longer, the standard deviations of 14 and 15 mm are as large as that difference, so the ranges mean ± SD overlap widely (57–85 mm against 69–99 mm). With only eight leaves in each sample the difference could easily be due to chance in which leaves were picked. The conclusion is therefore an overstatement: the data suggest a possible difference that would need larger samples and a statistical test to confirm. Because all the leaves are from one tree, any real difference would be environmental.", commonErrors: "Accepting the conclusion because the means differ." },
          { id: "q-3.1.6-di3", ref: R, stmts: ["3.1.6.s4", "3.1.6.s6"], type: "short", marks: 3, stem: "Dataset 3. (a) Which species shows more variation in seed mass? Explain how you can tell. (1 mark) (b) A student argues that the larger SD of species Y means 'its seeds are less reliable'. Comment. (2 marks)", scheme: [{ point: "Species Y: SD 4.0 mg v 1.8 mg, so a wider spread of values about its mean", marks: 1 }, { point: "But Y's mean is also 2.5× larger; relative to the mean the spread is similar (4.0/31.9 ≈ 13 %, 1.8/12.6 ≈ 14 %)", marks: 1 }, { point: "'Less reliable' is not justified: SD describes spread, not quality or reliability; large samples (n = 100) make the SDs themselves reliable estimates", marks: 1 }], model: "(a) Species Y shows more variation: its standard deviation of 4.0 mg is more than twice that of species X (1.8 mg), so its seed masses are spread more widely about the mean. (b) The larger SD partly reflects the larger mean: relative to the mean the two spreads are similar (about 13–14 %). Standard deviation describes how spread out the values are; it says nothing about whether the seeds are 'reliable' in any biological sense, so the student's claim is not justified. With 100 seeds per sample the means and SDs are themselves good estimates.", commonErrors: "Reading SD as a measure of quality." },
          { id: "q-3.1.6-di4", ref: R, stmts: ["3.1.6.s4"], type: "mcq", marks: 1, stem: "Which statement about standard deviation is correct?", options: ["A larger SD means a larger mean", "A larger SD means the values are more spread out about the mean", "SD alone shows whether two means differ significantly", "SD is the difference between the largest and smallest value"], answer: 1, explanation: "SD measures spread; the range is largest minus smallest; significance needs a test." },
          { id: "q-3.1.6-di5", ref: R, stmts: ["3.1.6.s2", "3.1.6.s4", "3.1.6.s6"], type: "mcq", marks: 1, stem: "Two samples have means of 50 and 54 with SDs of 12 and 13 and n = 6 each. The most justified statement is:", options: ["The populations definitely differ", "The samples differ, but the overlap and small sample sizes mean the difference may be due to chance", "The second population is more variable", "Sample size does not matter here"], answer: 1, explanation: "Large overlap, tiny samples: tentative." },
        ] },
      { kind: "sdCalculator", title: "How a Standard Deviation Is Calculated (supporting)", note: "Optional. Not required in OxfordAQA written papers; shown so that the number you interpret is not a mystery." },
    ],
    focus: [
      { slot: "snail-banding", title: "Banded snails in one population", ref: R, explanation: "<p>Grove snails (<em>Cepaea nemoralis</em>) from a single population show strikingly different shells: yellow, pink or brown, banded or unbanded. This is intraspecific variation with a largely genetic basis; the colour and banding are controlled by a small set of genes with several alleles, so the variation is discontinuous (distinct morphs rather than a continuous range). The proportions of the morphs differ between habitats, and classic studies showed that song thrushes, which hunt by sight, take the snails that are most conspicuous against each background, so selection by predators helps maintain the differences.</p>", question: { id: "q-3.1.6-fx1", ref: R, stmts: ["3.1.6.s2"], type: "short", marks: 3, stem: "A student collected 50 snails from a hedge by picking up every snail she could see in ten minutes. Explain why this sample might not be representative of the population, and describe a better method. (3 marks)", scheme: [{ point: "Snails that are more conspicuous (e.g. yellow against dark leaves) are more likely to be seen and picked: sampling bias", marks: 1 }, { point: "So the proportions of morphs in the sample will not match the population", marks: 1 }, { point: "Use random sampling: place quadrats at random coordinates along the hedge and search each one thoroughly, recording every snail found", marks: 1 }], model: "The method is biased because the student is more likely to see and pick up the conspicuous snails, for instance yellow shells on dark leaves, so those morphs will be over-represented and the proportions in the sample will not match the population. A representative sample needs random sampling: mark out the hedge, use random numbers to choose quadrat positions, and search each quadrat thoroughly so that every snail in it is recorded whatever its colour.", commonErrors: "Suggesting 'collect more snails the same way'." } },
      { slot: "hydrangea-colour", title: "One genotype, two colours", ref: R, explanation: "<p>In many varieties of <em>Hydrangea macrophylla</em>, plants with the same genotype can produce either blue or pink flowers. Whether a plant produces blue or pink flowers depends on the availability of aluminium ions, which in turn depends on soil pH: in acidic soil aluminium is soluble, taken up and binds the pigment to give blue; in neutral or alkaline soil it is unavailable and the same pigment appears pink. Gardeners change the colour by changing the soil, which is the clearest everyday demonstration that an environmental factor can alter a phenotype without any change in the genotype.</p>", question: { id: "q-3.1.6-fx2", ref: R, stmts: ["3.1.6.s5"], type: "short", marks: 2, stem: "Explain how you could show experimentally that flower colour in hydrangeas is determined by the environment rather than by the genotype. (2 marks)", scheme: [{ point: "Use cuttings from one plant (clones) so the genotype is identical", marks: 1 }, { point: "Grow them in soils of different pH / aluminium availability with other conditions controlled; if the colours differ, the difference must be environmental", marks: 1 }], model: "Take cuttings from a single hydrangea so that every plant has the same genotype, and grow them in soils that differ only in pH (and so in available aluminium), keeping light, water and nutrients the same. If the clones produce different flower colours, the difference can only be due to the environment, because their genes are identical.", commonErrors: "Comparing different plants, which confounds genotype and environment." } },
    ],
    examFocus: `<ul><li>Define both kinds of variation with "within a species" and "between species", and give an example of each.</li><li>Sampling: say <em>why</em> random (removes the sampler's bias; every individual equally likely), <em>how</em> (grid and random coordinates), and that chance still produces differences between samples; a larger sample reduces the effect of chance but not bias.</li><li>Normal distribution: symmetrical about the mean; quote the 68 % within ±1 SD rule when interpreting; a larger SD means more variation.</li><li>When comparing datasets quote the means, the SDs and n, comment on overlap, and keep conclusions tentative: SD alone does not show significance.</li><li>Genetic v environmental: use clones or identical twins as the test; remember the two can interact.</li></ul>`,
    synoptic: [
      { ref: "3.3.6.1", text: "Genotype and phenotype are defined formally in inheritance." },
      { ref: "3.3.8.1", text: "Phenotypic variation within a population is what natural selection acts on." },
      { ref: "3.1.9.1", text: "Meiosis and random fertilisation generate the genetic variation described here." },
      { ref: "3.3.1.2", text: "Analysing distribution data: correlations and causal relationships." },
    ],
    quickCheck: [
      { id: "q-3.1.6-qc1", ref: R, stmts: ["3.1.6.s1"], type: "mcq", marks: 1, stem: "Variation between members of the same species is called:", options: ["interspecific variation", "intraspecific variation", "continuous variation", "discontinuous variation"], answer: 1, explanation: "Intra = within." },
      { id: "q-3.1.6-qc2", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "Random sampling is used so that:", options: ["every sample has the same mean", "the sampler's choices cannot bias which individuals are measured", "the sample is as large as possible", "chance has no effect"], answer: 1, explanation: "Chance still operates; bias is removed." },
      { id: "q-3.1.6-qc3", ref: R, stmts: ["3.1.6.s3", "3.1.6.s4"], type: "gap", marks: 2, stem: "Complete the sentence.", text: "In a normal distribution about {{1}} % of the values lie within one standard deviation of the mean, and the distribution is {{2}} about the mean.", answers: { 1: ["68", "68.3", "68.27"], 2: ["symmetrical", "symmetric"] }, explanation: "68 %; symmetrical." },
      { id: "q-3.1.6-qc4", ref: R, stmts: ["3.1.6.s2", "3.1.6.s6"], type: "mcq", marks: 1, stem: "Two samples of the same species from different habitats have different mean masses. Which of these would NOT help you decide whether the difference is real?", options: ["Comparing the standard deviations and the overlap of the ranges", "Checking the sample sizes", "Repeating with larger random samples", "Choosing the heaviest individuals from each habitat"], answer: 3, explanation: "That introduces bias." },
    ],
    flashcards: [
      { id: "f-3.1.6-1", front: "Define intraspecific variation.", back: "Variation between members of the same species, e.g. shell colour in one population of snails." },
      { id: "f-3.1.6-2", front: "Define interspecific variation.", back: "Variation between different species, e.g. oak and beech leaves." },
      { id: "f-3.1.6-3", front: "Three possible causes of similarities and differences within a species (spec).", back: "Genetic factors; differences in environmental factors; a combination of both." },
      { id: "f-3.1.6-4", front: "Give an example of variation that is purely genetic.", back: "ABO blood group: fixed by inherited alleles, unaffected by the environment." },
      { id: "f-3.1.6-5", front: "Give an example of variation that is purely environmental.", back: "Clones of one hydrangea producing blue flowers in acidic soil and pink in alkaline soil; sun and shade leaves on one tree." },
      { id: "f-3.1.6-6", front: "How can you tell genetic from environmental variation experimentally?", back: "Hold one factor constant: clones / identical twins share a genotype, so differences between them are environmental; different genotypes in one controlled environment show genetic differences." },
      { id: "f-3.1.6-7", front: "Genotype v phenotype (supporting).", back: "Genotype: the alleles an organism has. Phenotype: its observable characteristics, from genotype, environment and their interaction." },
      { id: "f-3.1.6-8", front: "Why can't a phenotype always be split into a genetic share and an environmental share?", back: "Because genotype and environment interact: the effect of the environment can differ between genotypes, so the contributions are not simply additive." },
      { id: "f-3.1.6-9", front: "Why do we sample rather than measure the whole population?", back: "The population is too large (or too hard to reach) to measure; a representative sample estimates its properties." },
      { id: "f-3.1.6-10", front: "What makes a sample representative?", back: "Its distribution of values resembles the population's: achieved by random selection and an adequate sample size." },
      { id: "f-3.1.6-11", front: "Define random sampling and describe how it is done.", back: "Every individual has an equal chance of selection; e.g. grid the area and use random-number coordinates to place quadrats, measuring everything found in them." },
      { id: "f-3.1.6-12", front: "What is sampling bias? Give two examples.", back: "Selection that depends on the individual or the sampler's choice: picking typical-looking or large specimens; sampling only where access is easy." },
      { id: "f-3.1.6-13", front: "Why do two random samples from the same population differ?", back: "Chance: different individuals happen to be selected each time. Differences between samples include this chance element." },
      { id: "f-3.1.6-14", front: "Why does sample size matter?", back: "Larger random samples tend to give means closer to the population mean and a better picture of spread; chance differences become smaller relative to real ones." },
      { id: "f-3.1.6-15", front: "Does a larger sample remove bias?", back: "No: a large biased sample is still biased. Only the method (random selection) removes bias." },
      { id: "f-3.1.6-16", front: "Is a larger sample always closer to the population mean?", back: "Not on any single occasion; larger random samples tend to be closer, with the scatter of sample means falling in proportion to 1/√n." },
      { id: "f-3.1.6-17", front: "Describe a normal distribution.", back: "A symmetrical, bell-shaped distribution of a continuously varying characteristic, with most values near the mean and fewer at the extremes; mean, median and mode coincide." },
      { id: "f-3.1.6-18", front: "What does the mean measure?", back: "Central tendency: the typical value; sum of the values divided by their number." },
      { id: "f-3.1.6-19", front: "What does the standard deviation measure?", back: "The spread (dispersion) of values about the mean within a sample: small SD = clustered, large SD = widely spread (more variation)." },
      { id: "f-3.1.6-20", front: "What proportion of a normal distribution lies within ±1, ±2 and ±3 SD of the mean?", back: "About 68 %, 95 % and 99.7 % respectively." },
      { id: "f-3.1.6-21", front: "A sample has mean 30 mm, SD 4 mm. What range contains about two thirds of the values?", back: "26 to 34 mm (mean ± 1 SD)." },
      { id: "f-3.1.6-22", front: "Are you required to calculate SD in OxfordAQA written papers?", back: "No. You must understand and interpret it; the specification says calculation will not be required." },
      { id: "f-3.1.6-23", front: "Two groups: same mean, SDs 2 and 6. What does this tell you?", back: "The group with SD 6 is far more variable; its values spread three times as widely about the same centre." },
      { id: "f-3.1.6-24", front: "Why must overlapping distributions be interpreted carefully?", back: "If the mean ± SD ranges overlap, many individuals could belong to either group, so the difference in means may be due to chance; sample size and a statistical test are needed before claiming a real difference." },
      { id: "f-3.1.6-25", front: "Does standard deviation alone show whether a difference is significant?", back: "No. It describes spread; significance requires a statistical test that also takes sample size into account." },
      { id: "f-3.1.6-26", front: "Continuous v discontinuous variation (supporting).", back: "Continuous: any value in a range (height), many genes + environment, normal distribution. Discontinuous: distinct categories (blood group), one or few genes." },
      { id: "f-3.1.6-27", front: "Correlation v causation (supporting).", back: "Correlation: one variable changes with another. It does not prove one causes the other: reverse causation, a confounding variable or chance may explain it; a controlled experiment or mechanism is needed." },
      { id: "f-3.1.6-28", front: "What is a confounding variable?", back: "A third variable that affects both of the variables being compared and so can produce a correlation between them without any causal link." },
      { id: "f-3.1.6-29", front: "What information should you quote when comparing two datasets?", back: "The means, the standard deviations (and the overlap of mean ± SD), and the sample sizes; then a tentative conclusion." },
      { id: "f-3.1.6-30", front: "Why are identical twins useful in studies of variation?", back: "They share a genotype, so any difference between them must be environmental (or chance in development)." },
    ],
    questions: [
      { id: "q-3.1.6-m1", ref: R, stmts: ["3.1.6.s1"], type: "mcq", marks: 1, stem: "Which is an example of interspecific variation?", options: ["Different heights of people in a class", "Different shell colours in one snail population", "Differences between a lion and a tiger", "Different masses of seeds from one plant"], answer: 2, explanation: "Two species." },
      { id: "q-3.1.6-m2", ref: R, stmts: ["3.1.6.s5"], type: "mcq", marks: 1, stem: "Cuttings from one plant grown in different light intensities differ in leaf area. This variation is:", options: ["genetic", "environmental", "interspecific", "discontinuous"], answer: 1, explanation: "Clones share a genotype." },
      { id: "q-3.1.6-m3", ref: R, stmts: ["3.1.6.s5"], type: "mcq", marks: 1, stem: "Human height is influenced by:", options: ["genes only", "environment only", "both genes and environment", "neither"], answer: 2, explanation: "Many genes plus nutrition and health." },
      { id: "q-3.1.6-m4", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "The purpose of random sampling is to:", options: ["make the sample larger", "ensure every individual has an equal chance of selection, avoiding bias", "remove the effect of chance", "measure the whole population"], answer: 1, explanation: "Removes sampler bias." },
      { id: "q-3.1.6-m5", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "Which method of choosing quadrat positions is random?", options: ["Placing quadrats where the plants look typical", "Throwing quadrats over your shoulder", "Using random-number coordinates on a grid", "Placing quadrats every 2 m along a line"], answer: 2, explanation: "Throwing is not random (it depends on the thrower); every 2 m is systematic." },
      { id: "q-3.1.6-m6", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "Two random samples of 10 limpets from the same shore have means of 29.1 mm and 31.4 mm. The most likely explanation is:", options: ["the shore has two populations", "chance: different individuals were selected", "one sample was biased", "the measuring was wrong"], answer: 1, explanation: "Chance differences between samples are expected." },
      { id: "q-3.1.6-m7", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "Increasing the size of a random sample:", options: ["removes bias", "tends to reduce the effect of chance on the sample mean", "guarantees the sample mean equals the population mean", "makes the standard deviation zero"], answer: 1, explanation: "Reduces, does not remove, chance effects." },
      { id: "q-3.1.6-m8", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "A student measures the 30 largest fish in a pond. The main problem is:", options: ["the sample is too small", "the sample is biased, so the mean will overestimate the population mean", "the sample is random", "the standard deviation will be too large"], answer: 1, explanation: "Deliberate selection is bias." },
      { id: "q-3.1.6-m9", ref: R, stmts: ["3.1.6.s3"], type: "mcq", marks: 1, stem: "In a normal distribution:", options: ["most values are at the extremes", "the distribution is symmetrical about the mean", "the mean is larger than the median", "the standard deviation is zero"], answer: 1, explanation: "Bell shape, symmetrical." },
      { id: "q-3.1.6-m10", ref: R, stmts: ["3.1.6.s3", "3.1.6.s4"], type: "mcq", marks: 1, stem: "A sample has mean 50 g and SD 5 g. About 95 % of values lie between:", options: ["45 and 55 g", "40 and 60 g", "35 and 65 g", "50 and 60 g"], answer: 1, explanation: "±2 SD." },
      { id: "q-3.1.6-m11", ref: R, stmts: ["3.1.6.s4"], type: "mcq", marks: 1, stem: "Which measure describes how spread out values are around the mean?", options: ["The mean", "The median", "The standard deviation", "The sample size"], answer: 2, explanation: "SD = spread." },
      { id: "q-3.1.6-m12", ref: R, stmts: ["3.1.6.s4"], type: "mcq", marks: 1, stem: "Dataset P: mean 40, SD 3. Dataset Q: mean 40, SD 9. Which statement is correct?", options: ["Q shows more variation than P", "P shows more variation than Q", "P and Q are identical", "Q has a larger mean"], answer: 0, explanation: "Larger SD, more spread." },
      { id: "q-3.1.6-m13", ref: R, stmts: ["3.1.6.s4", "3.1.6.s6"], type: "mcq", marks: 1, stem: "Two means differ, but their mean ± SD ranges overlap considerably. The best conclusion is:", options: ["the populations are definitely different", "the populations are definitely the same", "the difference may be due to chance; a statistical test is needed", "the standard deviations are wrong"], answer: 2, explanation: "Overlap = caution." },
      { id: "q-3.1.6-m14", ref: R, stmts: ["3.1.6.s4"], type: "mcq", marks: 1, stem: "Which of these is required of you in OxfordAQA written papers?", options: ["Calculate a standard deviation from raw data", "Interpret a standard deviation given with a mean", "Derive the normal distribution equation", "Derive the formula for standard deviation"], answer: 1, explanation: "Interpretation only; calculation is stated as not required." },
      { id: "q-3.1.6-m15", ref: R, stmts: ["3.1.6.s6"], type: "mcq", marks: 1, stem: "A study finds that people who own more books have higher exam grades. The safest interpretation is:", options: ["owning books causes higher grades", "a correlation that may reflect a confounding variable such as family income or interest in study", "grades cause people to buy books", "there is no relationship"], answer: 1, explanation: "Correlation is not causation." },
      { id: "q-3.1.6-m16", ref: R, stmts: ["3.1.6.s5", "3.1.6.s6"], type: "mcq", marks: 1, stem: "Identical twins reared apart show more similar heights than unrelated people reared together. This suggests that height:", options: ["is entirely environmental", "has a substantial genetic component", "is interspecific", "cannot vary"], answer: 1, explanation: "Shared genotype, different environments." },
      { id: "q-3.1.6-m23", ref: R, stmts: ["3.1.6.s3", "3.1.6.s2"], type: "mcq", marks: 1, stem: "A student measured the length of 5 randomly chosen leaves from a hedge and then repeated the investigation with 50 randomly chosen leaves. What is the main advantage of the larger sample?", options: ["The sample mean is more likely to be close to the mean of the whole population", "The effect of chance on the sample mean is removed completely", "The leaf lengths will now be normally distributed", "The standard deviation of the whole population becomes smaller"], answer: 0, explanation: "A larger random sample is more likely to be representative, so its mean is more likely to be near the population mean. Chance still affects any sample (it is reduced, not removed); sample size does not change the population's distribution or its standard deviation." },
      { id: "q-3.1.6-m18", ref: R, stmts: ["3.1.6.s4", "3.1.6.s2"], type: "mcq", marks: 1, stem: "Why should the mean of a sample be quoted with its standard deviation and sample size?", options: ["To make the table longer", "Because the mean alone says nothing about spread or how reliable the estimate is", "Because the SD is the mean", "Because sample size equals SD"], answer: 1, explanation: "Spread and n qualify the mean." },
      { id: "q-3.1.6-m19", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "A systematic sample every 5 m along a transect is appropriate when:", options: ["you want every individual to have an equal chance", "you want to describe a change along a gradient", "the population is uniform", "you want to avoid measuring"], answer: 1, explanation: "Transects for gradients; random for unbiased estimates." },
      { id: "q-3.1.6-m20", ref: R, stmts: ["3.1.6.s2"], type: "mcq", marks: 1, stem: "The 'importance of chance' in sampling refers to the fact that:", options: ["samplers choose at random", "which individuals end up in a random sample is a matter of chance, so samples differ", "chance determines the species", "chance replaces the need for a large sample"], answer: 1, explanation: "Sampling variation." },
      { id: "q-3.1.6-g1", ref: R, stmts: ["3.1.6.s1", "3.1.6.s2"], type: "gap", marks: 4, stem: "Complete the passage.", text: "Variation within a species is called {{1}} variation. To investigate it fairly, individuals are chosen by {{2}} sampling so that every individual has an equal chance of selection. Even so, {{3}} causes samples to differ, so an appropriate {{4}} size is needed for the data to be representative.", answers: { 1: ["intraspecific"], 2: ["random"], 3: ["chance"], 4: ["sample"] }, explanation: "Intraspecific; random; chance; sample." },
      { id: "q-3.1.6-g2", ref: R, stmts: ["3.1.6.s3", "3.1.6.s4"], type: "gap", marks: 3, stem: "Complete the passage.", text: "In a normal distribution the values are {{1}} about the mean. The {{2}} deviation measures their spread; about {{3}} % of values lie within one of them either side of the mean.", answers: { 1: ["symmetrical", "symmetric", "symmetrically distributed"], 2: ["standard"], 3: ["68", "68.3", "68.27"] }, explanation: "Symmetrical; standard; 68." },
      { id: "q-3.1.6-match1", ref: R, stmts: ["3.1.6.s2"], type: "match", marks: 4, stem: "Match each sampling method to its description.", pairs: [{ left: "Random sampling", right: "Random-number coordinates decide the positions; no sampler choice" }, { left: "Systematic sampling", right: "Positions at fixed intervals along a line, used for gradients" }, { left: "Convenience sampling", right: "The individuals easiest to reach: biased" }, { left: "Deliberate selection", right: "The sampler chooses 'good' specimens: biased" }] },
      { id: "q-3.1.6-match2", ref: R, stmts: ["3.1.6.s3", "3.1.6.s4", "3.1.6.s2"], type: "match", marks: 4, stem: "Match each term to its meaning.", pairs: [{ left: "Mean", right: "Measure of central tendency: sum of values ÷ number of values" }, { left: "Standard deviation", right: "Measure of spread of values about the mean" }, { left: "Normal distribution", right: "Symmetrical bell-shaped distribution about the mean" }, { left: "Representative sample", right: "A sample whose values reflect the population's distribution" }] },
      { id: "q-3.1.6-d1", ref: R, stmts: ["3.1.6.s4", "3.1.6.s6", "3.1.6.s5"], type: "short", marks: 4, stem: "Data. Students measured the lengths of ivy leaves on the north (shaded) and south (sunny) sides of a wall. North: n = 40, mean 62 mm, SD 6 mm. South: n = 40, mean 48 mm, SD 5 mm. (a) Describe the difference between the two sets of leaves using all the data. (2 marks) (b) Suggest whether the difference is genetic or environmental, and explain how the students could test this. (2 marks)", scheme: [{ point: "North leaves have a larger mean (62 v 48 mm, a difference of 14 mm)", marks: 1 }, { point: "SDs similar (6, 5 mm) and mean ± SD ranges (56–68 v 43–53) do not overlap; n = 40 each: a real difference is likely", marks: 1 }, { point: "Likely environmental (light/shade) but the data cannot rule out genetic differences between plants on each side", marks: 1 }, { point: "Test: compare leaves of the same plant / clones grown in sun and shade, or grow cuttings from both sides in identical conditions", marks: 1 }], model: "(a) Leaves on the shaded north side have a mean length 14 mm greater than those on the south side (62 against 48 mm). The standard deviations are similar (6 and 5 mm) and the ranges mean ± SD (56–68 mm and 43–53 mm) do not overlap; with 40 leaves in each sample the difference is unlikely to be due to chance. (b) The difference is probably environmental, a response to light, but the data alone cannot exclude a genetic difference between the plants on the two sides. To test it, the students could compare leaves from one plant that grows round the corner of the wall, or take cuttings from each side and grow them under identical conditions: if the difference disappears it was environmental.", commonErrors: "Stating 'environmental' without a test." },
      { id: "q-3.1.6-d2", ref: R, stmts: ["3.1.6.s2"], type: "short", marks: 3, stem: "Data. A student took five random samples of 10 daisies each from a lawn and found the mean flower diameters 21.2, 19.8, 22.5, 20.4 and 21.9 mm. Another student took one sample of 50 and found a mean of 21.1 mm. Explain why the five means differ from each other, and why the sample of 50 is likely to give a better estimate of the population mean. (3 marks)", scheme: [{ point: "Different individuals were selected by chance in each sample, so the means vary (sampling variation)", marks: 1 }, { point: "A larger sample includes more of the population's variation, so extreme individuals have less influence on the mean", marks: 1 }, { point: "So the mean of a larger random sample tends to lie closer to the population mean (though not guaranteed on one occasion)", marks: 1 }], model: "Each sample of 10 contains a different set of daisies chosen by chance, so the sample means scatter around the population mean; this is sampling variation. In a sample of 50 any unusually large or small daisies are outweighed by the many others, so the sample reflects the population's spread better and its mean tends to lie closer to the population mean, although a larger sample is not guaranteed to be closer on every single occasion.", commonErrors: "Saying the five students 'made mistakes'." },
      { id: "q-3.1.6-s1", ref: R, stmts: ["3.1.6.s2"], type: "short", marks: 3, stem: "Describe how you would obtain a random sample of 30 plants of one species in a field, and explain why random sampling is necessary. (3 marks)", scheme: [{ point: "Mark out the field with a grid / two tape measures at right angles", marks: 1 }, { point: "Use random numbers to generate coordinates; place a quadrat at each and record the plants in it until 30 are measured", marks: 1 }, { point: "Random sampling removes the sampler's bias so that the sample is representative of the population", marks: 1 }], model: "Lay two tape measures at right angles along the edges of the field to form a grid, use a random-number generator to produce pairs of coordinates, and place a quadrat at each pair, measuring the plants of the chosen species in it until 30 have been recorded. Random sampling is necessary because it gives every plant an equal chance of being selected, so the sampler's choices cannot bias the sample and it should be representative of the whole population.", commonErrors: "'Throw the quadrat randomly'." },
      { id: "q-3.1.6-s2", ref: R, stmts: ["3.1.6.s4"], type: "short", marks: 3, stem: "Explain what a standard deviation tells you about a set of measurements, and why two samples with the same mean can still differ in an important way. (3 marks)", scheme: [{ point: "SD measures the spread of values about the mean", marks: 1 }, { point: "Small SD: values clustered near the mean; large SD: widely spread (more variation); about 68 % lie within ±1 SD", marks: 1 }, { point: "Same mean but different SDs: one sample is much more variable, e.g. a wider range of sizes, which may matter biologically (e.g. different conditions or more genetic diversity)", marks: 1 }], model: "The standard deviation measures how widely the measurements are spread about the mean: with a small SD most values lie close to the mean, with a large SD they are widely scattered, and in a normal distribution about 68 % of values lie within one SD either side of the mean. Two samples with the same mean can have very different SDs, meaning one population is far more variable than the other; that difference in variation can itself be important, for instance pointing to a wider range of conditions or greater genetic diversity.", commonErrors: "Confusing SD with range." },
      { id: "q-3.1.6-s3", ref: R, stmts: ["3.1.6.s5"], type: "short", marks: 3, stem: "Explain why similarities and differences between members of a species may result from a combination of genetic and environmental factors, using an example. (3 marks)", scheme: [{ point: "Genetic: individuals inherit different alleles that affect the characteristic", marks: 1 }, { point: "Environmental: factors such as nutrition, light or temperature influence how the characteristic develops", marks: 1 }, { point: "Example with both, e.g. human height: alleles set the potential, diet and health determine how far it is reached (or plant height: genotype and light/nutrients)", marks: 1 }], model: "Individuals inherit different combinations of alleles, and many of these affect characteristics such as height, so part of the variation is genetic. The environment in which each individual develops, its nutrition, light, temperature or disease exposure, also affects the characteristic. Human height shows both: a person's alleles set their potential height, while diet and health in childhood determine how much of it is reached, so two people with similar genotypes can differ, and so can two with different genotypes raised identically.", commonErrors: "Giving an example that is purely one or the other." },
      { id: "q-3.1.6-e1", ref: R, stmts: ["3.1.6.s2", "3.1.6.s4", "3.1.6.s6"], type: "extended", marks: 6, stem: "Extended response. A biologist wants to compare the shell length of a species of limpet on two shores and to decide whether any difference is real. Describe how she should collect and analyse the data, and explain how she should interpret the means and standard deviations she obtains. (6 marks)", scheme: [{ point: "Random sampling on each shore (grid, random coordinates, quadrats) so every limpet has an equal chance; same method on both shores", marks: 1 }, { point: "Adequate and equal sample sizes (e.g. 30+) so that chance differences are small and the data representative", marks: 1 }, { point: "Measure each shell length the same way; calculate the mean and standard deviation for each shore", marks: 1 }, { point: "Compare the means; interpret the SDs as the spread of each sample (≈ 68 % within ±1 SD)", marks: 1 }, { point: "Consider overlap of mean ± SD: large overlap means the difference may be due to chance", marks: 1 }, { point: "Use a statistical test to decide significance; conclusions tentative; a difference does not show its cause (exposure, food, predation confounded)", marks: 1 }], levels: "Level 3 (5–6): random method with reasons, adequate n, means and SDs calculated and interpreted with overlap and a test, and a tentative conclusion. Level 2 (3–4): method and some interpretation. Level 1 (1–2): fragments.", model: "On each shore she should mark out a grid with tape measures and use random numbers to choose quadrat positions, measuring every limpet in each quadrat until she has a large sample, at least 30 per shore, collected by the same method so that the samples are representative and unbiased. She should measure each shell with the same calipers along the same axis, then calculate the mean and standard deviation for each shore. The means show the typical size on each shore; the standard deviations show how variable the limpets are, with about 68 % of each sample lying within one SD of its mean. If the mean ± SD ranges of the two shores overlap widely, the difference between the means may be due to chance in which limpets were selected, whereas little overlap with large samples suggests a real difference. To decide, she should apply a statistical test and state the conclusion tentatively; even a significant difference would not show its cause, because wave exposure, food supply and predators all differ between shores.", commonErrors: "Treating a difference in means as conclusive; omitting the sampling method." },
    ],
  };
})();
